      "enum": [
        "landscape_construction",
        "custom_pool",
        "outdoor_kitchen",
        "hardscaping",
        "premium_renovation"
      ]
    },
    "project_id": {
      "type": "string",
      "pattern": "^SYN-[A-Za-z0-9_-]{1,48}$"
