    "source_ref": {
      "type": "string",
      "pattern": "^SYN-[A-Za-z0-9_-]{1,48}$"
    },
    "transaction_id": {
      "type": "string",
      "pattern": "^SYN-[A-Za-z0-9_-]{1,48}$"
    },
    "collection": {
      "const": "synthetic"
    },
    "items": {
      "type": "array",
      "minItems": 1,
      "maxItems": 20,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "item_id",
          "price_cents",
          "quantity"
        ],
        "properties": {
          "item_id": {
            "enum": [
              "landscape_construction",
              "custom_pool",
              "outdoor_kitchen",
              "hardscaping",
              "premium_renovation"
